import{_ as a,o as r,c as t,a3 as o}from"./chunks/framework.D5HvAqso.js";const g=JSON.parse('{"title":"What is DragDoll React?","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://niklasramo.github.io/dragdoll/react/"}],["meta",{"property":"og:url","content":"https://niklasramo.github.io/dragdoll/react/"}]]},"headers":[],"relativePath":"react/index.md","filePath":"react/index.md","lastUpdated":1778006798000}'),n={name:"react/index.md"};function l(i,e,s,d,c,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="what-is-dragdoll-react" tabindex="-1">What is DragDoll React? <a class="header-anchor" href="#what-is-dragdoll-react" aria-label="Permalink to &quot;What is DragDoll React?&quot;">​</a></h1><p>DragDoll React is a thin and performant React (18+) wrapper for the <a href="/dragdoll/">DragDoll</a> drag-and-drop system. It provides React hooks that give you access to the full DragDoll API while minimizing re-renders and maintaining excellent performance.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><p>🎯   <strong>Thin Wrapper</strong>: Minimal overhead, direct access to vanilla DragDoll API.</p><p>🚀   <strong>High Performance</strong>: Optimized with stable references and minimal re-renders.</p><p>💪   <strong>Type Safe</strong>: Full TypeScript support with excellent type inference.</p><p>🍦   <strong>Vanilla Underneath</strong>: Full access to the underlying DragDoll API when you need it.</p><p>💝   <strong>Free &amp; Open Source</strong>: 100% MIT licensed.</p><h2 id="caveats" tabindex="-1">Caveats <a class="header-anchor" href="#caveats" aria-label="Permalink to &quot;Caveats&quot;">​</a></h2><p>Being a wrapper over a vanilla JS library often comes with a few caveats, and such is the case with this wrapper also. The <a href="/dragdoll/draggable#container"><code>container</code></a> option of the <a href="/dragdoll/draggable"><code>Draggable</code></a> class is only <em>partially</em> supported because it will make the core library move DOM nodes under a different node for the duration of the drag. React has its own API (<a href="https://react.dev/reference/react-dom/createPortal" target="_blank" rel="noreferrer"><code>createPortal</code></a>) for moving DOM nodes around, which is very tricky to support in a wrapper. Read more about this in the <a href="/dragdoll/react/use-draggable#container"><code>useDraggable</code></a> docs.</p>',10)])])}const f=a(n,[["render",l]]);export{g as __pageData,f as default};
